create temp table r_baseline on commit drop as
  select (select count(*) from public.places) as places,
         (select count(*) from public.places where status = 'approved') as approved,
         (select count(*) from public.agent_log) as logs;

do $$
begin
  if (select count(*) from r) <> 59 then raise exception 'guarda: la lista no tiene 59 filas'; end if;
  if (select count(*) from public.places p join r on r.id = p.id
        where p.status = 'approved' and p.validation_confidence = r.old_conf
          and coalesce(p.validation_notes, '') !~* 'validaci[oó]n retroactiva'
          and ((not r.in23 and p.updated_at = r.expected_updated_at
                and coalesce(p.validation_notes, '') !~* '(override|aprobaci[oó]n manual|correcci[oó]n manual)')
            or (r.in23 and p.safety_level = 'celiac_friendly'
                and p.validation_notes like 'CORRECCIÓN MANUAL (2026-11-20, Santiago Sánchez): sin evidencia explícita de 100 del propio local.%'))) <> 59 then
    raise exception 'guarda: las 59 filas no están como se leyeron (o falta aplicar los 23 primero)';
  end if;
end $$;

update public.places p
   set status = r.status,
       validation_confidence = r.conf,
       category = coalesce(r.category, p.category),
       safety_level = r.safety,
       flags = case when coalesce(p.flags, '[]'::jsonb) @> '["100% pendiente de confirmación del administrador"]'::jsonb
                     and not r.flags @> '["100% pendiente de confirmación del administrador"]'::jsonb
                    then r.flags || '["100% pendiente de confirmación del administrador"]'::jsonb else r.flags end,
       recommendation = r.recommendation,
       validation_notes = concat_ws(E'
', r.prefix,
         '--- Nota original (rubric binario): ' || nullif(btrim(p.validation_notes), ''))
  from r
 where p.id = r.id;

insert into public.agent_log (agent, action, result, status)
values ('validator', 'revalidate_retroactive_complete',
        jsonb_build_object('apply', true, 'threshold', 0.85, 'seen', 59,
                           'stayed_approved', 1, 'to_needs_review', 58, 'to_discarded', 0, 'gate_discarded_kept_in_review', 8,
                           'source', 'db/fixes/2026-11-20-revalidacion-menor-085.sql (valores del dry-run del 2026-11-20)',
                           'llm_calls', 59, 'cost_usd', 0.2945),
        'success');

do $$
begin
  if (select count(*) from public.places p join r on r.id = p.id
        where p.status = r.status and p.validation_confidence is not distinct from r.conf and p.safety_level = r.safety
          and p.validation_notes like 'RE-VALIDACIÓN RETROACTIVA (2026-11-20)%') <> 59 then
    raise exception 'guarda: no quedaron las 59 filas como se esperaba';
  end if;
  if (select places from r_baseline) <> (select count(*) from public.places)
     or (select approved from r_baseline) - 58 <> (select count(*) from public.places where status = 'approved')
     or (select logs from r_baseline) + 1 <> (select count(*) from public.agent_log) then
    raise exception 'guarda: cambió algo más de lo previsto (lugares, aprobados o agent_log)';
  end if;
end $$;

select p.name, p.city, p.country, p.status, p.safety_level, p.validation_confidence, p.flags,
       left(p.validation_notes, 300) as nota
  from public.places p join r on r.id = p.id order by p.status, p.country, p.city, p.name;

commit;
